import { makeBundleRef, parseBundleRef } from "../../core/asset/asset-ref.js";
import { rethrowIfTestIsolationError } from "../../core/errors.js";
import { appendEvent, readEvents } from "../../core/events.js";
import { withStateDbTelemetry } from "../../core/state-db.js";
import { TELEMETRY_BUSY_TIMEOUT_MS, withIndexDb } from "../../storage/repositories/index-db.js";
import { findEntryIdByRef, getEntryById, getEntryIdByFilePath, getItemRefById, } from "../../storage/repositories/index-entries-repository.js";
import { usageEventAttributionMetadata } from "../search/search-attribution.js";
import { insertUsageEvent } from "./usage-events.js";
/** Count prior show events in the current one-hour loop-detection window. */
export function recentShowCount(ref) {
    try {
        return readEvents({
            type: "show",
            ref,
            since: new Date(Date.now() - 60 * 60 * 1000).toISOString(),
        }).events.length;
    }
    catch {
        return 0;
    }
}
/** Compare search/display selectors by their durable parent asset identity. */
function traceParentRef(ref) {
    try {
        const parsed = parseBundleRef(ref);
        return makeBundleRef(parsed.bundle, parsed.conceptId);
    }
    catch {
        // Registry result refs are not local bundle refs and cannot have a local
        // selector. Keep their existing exact comparison behavior.
        return ref;
    }
}
function appendShowTrace(ref, type, name) {
    appendEvent({ eventType: "show", ref, metadata: { type, name } });
    try {
        const { events: recentSearches } = readEvents({
            type: "search",
            since: new Date(Date.now() - 60_000).toISOString(),
        });
        const cutoffMs = Date.now() - 60_000;
        const matchingSearch = [...recentSearches].reverse().find((event) => {
            if (!event.ts || new Date(event.ts).getTime() < cutoffMs)
                return false;
            const refs = event.metadata?.resultRefs ?? [];
            return refs.some((candidate) => traceParentRef(candidate) === ref);
        });
        if (!matchingSearch)
            return;
        const resultRefs = matchingSearch.metadata?.resultRefs ?? [];
        appendEvent({
            eventType: "select",
            ref,
            metadata: {
                query: matchingSearch.metadata?.query,
                searchTs: matchingSearch.ts,
                searchId: matchingSearch.metadata?.searchId,
                source: matchingSearch.metadata?.source,
                rankPosition: resultRefs.findIndex((candidate) => traceParentRef(candidate) === ref),
            },
        });
    }
    catch {
        // Selection attribution is best-effort.
    }
}
function insertShowUsage(entryId, entryRef, derivedFrom, eventSource, project) {
    withStateDbTelemetry((stateDb) => {
        insertUsageEvent(stateDb, {
            event_type: "show",
            entry_ref: entryRef,
            entry_id: entryId,
            metadata: usageEventAttributionMetadata(derivedFrom ? { memoryInference: { exposure: "direct" } } : undefined, entryRef, "full", project),
            source: eventSource,
        });
    }, TELEMETRY_BUSY_TIMEOUT_MS);
}
/** Record a successful show using the already-rendered response identity. */
export function recordShowUsage(ref, type, name, eventSource = "user", filePath, project) {
    const parsed = parseBundleRef(ref);
    const eventRef = makeBundleRef(parsed.bundle, parsed.conceptId);
    appendShowTrace(eventRef, type, name);
    try {
        withIndexDb((db) => {
            const entryId = filePath ? getEntryIdByFilePath(db, filePath) : findEntryIdByRef(db, eventRef);
            if (entryId === undefined)
                return;
            const entryRef = getItemRefById(db, entryId);
            if (!entryRef)
                return;
            insertShowUsage(entryId, entryRef, getEntryById(db, entryId)?.entry.derivedFrom, eventSource, project);
        }, { busyTimeoutMs: TELEMETRY_BUSY_TIMEOUT_MS });
    }
    catch (error) {
        rethrowIfTestIsolationError(error);
    }
}
/**
 * Record a nested execution-source read only after dispatch has crossed
 * preflight. The caller holds the source's durable `bundle//conceptId` ref, so
 * no index connection is opened.
 */
export function recordIndexedShowUsage(ref, type, name, eventSource = "user") {
    appendShowTrace(ref, type, name);
    try {
        insertShowUsage(undefined, ref, undefined, eventSource);
    }
    catch (error) {
        rethrowIfTestIsolationError(error);
    }
}
